INSERT INTO `menu_items` (`item_id`, `description_en`, `description_vi`, `discount`, `image_url`, `is_available`, `name_en`, `name_vi`, `price`, `category_id`) VALUES (37, 'Refreshing cuban cocktail with white rum, sugar, lime, mint, and soda.', 'Cocktail Cuba sảng khoái kết hợp rượu rum trắng, đường, chanh, bạc hà và soda.', 0, "https://www.huongnghiepaau.com/wp-content/uploads/2018/05/mojito-la-thuc-uong-noi-tieng.jpg", b'1', 'Mojito', 'Cocktail Mojito (Rượu Rum, chanh, bạc hà & Soda)', 190000.00, 7);
INSERT INTO `menu_items` (`item_id`, `description_en`, `description_vi`, `discount`, `image_url`, `is_available`, `name_en`, `name_vi`, `price`, `category_id`) VALUES (38, 'Prestigious French Champagne with crisp, balanced flavors and fine bubbles.', 'Sâm-panh Pháp danh tiếng với hương vị cân bằng, tươi mát và bọt sủi mịn.', 0, "https://kentstreetcellars.com.au/cdn/shop/files/lifestyle-2-moet-chandon-imperial-brut-nv-750ml.jpg?v=1730954393", b'1', 'Moët & Chandon Brut', 'Sâm-panh Pháp Moët & Chandon', 3200000.00, 8);
INSERT INTO `menu_items` (`item_id`, `description_en`, `description_vi`, `discount`, `image_url`, `is_available`, `name_en`, `name_vi`, `price`, `category_id`) VALUES (39, 'Elegant French red wine from Bordeaux with notes of dark fruits.', 'Vang đỏ Pháp thanh lịch vùng Bordeaux với hương vị trái cây sẫm màu.', 0, "https://bizweb.dktcdn.net/100/299/056/files/ruou-vang-mouton-cadet-bordeaux.jpg?v=1622803817143", b'1', 'Bordeaux Rouge', 'Vang đỏ Pháp vùng Bordeaux', 1400000.00, 8);
INSERT INTO `menu_items` (`item_id`, `description_en`, `description_vi`, `discount`, `image_url`, `is_available`, `name_en`, `name_vi`, `price`, `category_id`) VALUES (40, 'Classic Tuscan red wine with vibrant acidity and cherry undertones.', 'Vang đỏ Tuscan cổ điển từ Ý với độ chua sống động và hương anh đào.', 0, "https://winecenter.vn/uploads/images/624c028356340a3bf4c4f4b7/Chianti.jpg", b'1', 'Chianti Classico', 'Vang đỏ Ý vùng Chianti', 1650000.00, 8);
INSERT INTO `menu_items` (`item_id`, `description_en`, `description_vi`, `discount`, `image_url`, `is_available`, `name_en`, `name_vi`, `price`, `category_id`) VALUES (41, 'Refined French Burgundy red wine showcasing delicate red berry flavors.', 'Vang đỏ Pháp tinh tế vùng Burgundy thể hiện hương vị quả mọng đỏ nhẹ nhàng.', 0, "https://worldwine.com.au/cdn/shop/files/vin-636.jpg?v=1709655633&width=1000", b'1', 'Burgundy Pinot Noir', 'Vang đỏ Pháp vùng Burgundy', 2100000.00, 8);
